class Book:
    def __init__(self, title):
        self.title = title
        self.out = False
    def __str__(self):
        return self.title
class Library:
    def __init__(self):
        self.books = []
    def add(self, title):
        self.books.append(Book(title))
    def borrow(self, t):
        for b in self.books:
            if b.title == t:
                if not b.out:
                    b.out = True
                    return True
        return False
    def give_back(self, t):
        for b in self.books:
            if b.title == t and b.out:
                b.out = False
                return True
        return False
lib = Library()
lib.add("Dune")
lib.add("Demian")
lib.add("Hamlet")
n = int(input())
for i in range(n):
    parts = input().split()
    if parts[0] == "borrow":
        if lib.borrow(parts[1]):
            print("Borrow OK")
        else:
            print("Borrow failed")
    else:
        if lib.give_back(parts[1]):
            print("Return OK")
        else:
            print("Return failed")
count = 0
for b in lib.books:
    if b.out:
        count = count + 1
print("On loan: " + str(count))
for b in lib.books:
    if b.out:
        print(b)

